-- =============================================================================
-- EcoRecife · Seed 002: rotas DEMONSTRATIVAS dos caminhões de coleta
-- -----------------------------------------------------------------------------
-- NENHUMA rota abaixo é oficial: não representam os roteiros reais da Emlurb nem
-- vêm de integração com a frota. Todas são gravadas com demonstrativo = true e
-- servem só para a simulação de coleta (docs/04, "Seeds de rotas").
--
-- Fonte e créditos:
--   Malha viária © colaboradores do OpenStreetMap (https://www.openstreetmap.org/copyright),
--   licença ODbL. Trajetos calculados uma única vez, em 29/10/2026, pelo servidor
--   público de demonstração do OSRM (https://router.project-osrm.org, perfil driving,
--   overview=full, geometries=geojson). Nenhuma chamada externa acontece na carga.
--   Os pontos de passagem formam um losango de ~450 m (N, L, S, O, N) em volta da
--   coordenada do bairro no seed 001; o OSRM encaixa cada um na rua mais próxima e
--   devolve o traçado sobre as ruas. As coordenadas abaixo são as do OSRM, sem edição.
--   #04 Boa Viagem    4.8 km, 134 pontos. Passagens (lat,lng): -8.121,-34.901 → -8.125,-34.897 → -8.129,-34.901 → -8.125,-34.905 → -8.121,-34.901
--   #06 Encruzilhada  4.2 km, 107 pontos. Passagens (lat,lng): -8.0328,-34.8918 → -8.0368,-34.8878 → -8.0408,-34.8918 → -8.0368,-34.8958 → -8.0328,-34.8918
--   #08 Casa Amarela  5.0 km, 209 pontos. Passagens (lat,lng): -8.022,-34.918 → -8.026,-34.914 → -8.03,-34.918 → -8.026,-34.922 → -8.022,-34.918
--   #11 Várzea        4.7 km, 103 pontos. Passagens (lat,lng): -8.0466,-34.9588 → -8.0506,-34.9548 → -8.0546,-34.9588 → -8.0506,-34.9628 → -8.0466,-34.9588
--   #13 Cordeiro      6.2 km, 152 pontos. Passagens (lat,lng): -8.0434,-34.9287 → -8.0474,-34.9247 → -8.0514,-34.9287 → -8.0474,-34.9327 → -8.0434,-34.9287
--   #15 Ibura         4.3 km, 165 pontos. Passagens (lat,lng): -8.1148,-34.9425 → -8.1188,-34.9385 → -8.1228,-34.9425 → -8.1188,-34.9465 → -8.1148,-34.9425
--   #17 Vasco da Gama 5.5 km, 308 pontos. Passagens (lat,lng): -8.0078,-34.9174 → -8.0118,-34.9134 → -8.0158,-34.9174 → -8.0118,-34.9214 → -8.0078,-34.9174
--
-- Uso:
--   - banco novo: aplicado depois do seed 001 por "pnpm db:seed" ou por instalar.sql;
--   - banco já instalado: "pnpm db:seed-rotas" (docs/03-banco-de-dados.md).
-- Segurança (as verificações abaixo rodam antes de qualquer gravação):
--   - exige os 7 veículos do seed 001, ativos;
--   - se as 7 rotas já existem exatamente como aqui, não faz nada (idempotente);
--   - carga parcial, rota demonstrativa alterada ou veículo que já tem outra rota:
--     interrompe com erro e não grava nada. Nunca apaga nem altera rotas existentes.
-- =============================================================================
BEGIN;

CREATE TEMP TABLE carga_rotas (
  codigo varchar(10)  PRIMARY KEY,
  nome   varchar(120) NOT NULL UNIQUE
) ON COMMIT DROP;


CREATE TEMP TABLE carga_rota_pontos (
  codigo    varchar(10)  NOT NULL REFERENCES carga_rotas (codigo),
  ordem     integer      NOT NULL,
  latitude  numeric(9,6) NOT NULL,
  longitude numeric(9,6) NOT NULL,
  PRIMARY KEY (codigo, ordem)
) ON COMMIT DROP;


-- Decide entre carregar e não fazer nada; qualquer estado inseguro interrompe.
CREATE TEMP TABLE carga_decisao (carregar boolean NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  total      constant integer := (SELECT count(*) FROM carga_rotas);
  existentes integer;
  lista      text;
BEGIN
  SELECT string_agg(c.codigo, ', ' ORDER BY c.codigo) INTO lista
    FROM carga_rotas c
   WHERE NOT EXISTS (SELECT 1 FROM veiculos v WHERE v.codigo = c.codigo AND v.ativo);
  IF lista IS NOT NULL THEN
    RAISE EXCEPTION 'Veículos ausentes ou inativos: %. Aplique o seed 001 antes das rotas', lista;
  END IF;

  SELECT count(*) INTO existentes FROM rotas r JOIN carga_rotas c ON c.nome = r.nome;

  IF existentes = 0 THEN
    SELECT string_agg(v.codigo || ' (' || r.nome || ')', ', ' ORDER BY v.codigo) INTO lista
      FROM rotas r
      JOIN veiculos v ON v.id = r.veiculo_id
      JOIN carga_rotas c ON c.codigo = v.codigo;
    IF lista IS NOT NULL THEN
      RAISE EXCEPTION 'Veículos que já têm rota cadastrada: %. Nada foi alterado; revise essas rotas antes de carregar as demonstrativas', lista;
    END IF;

  ELSIF existentes = total THEN
    -- Já carregadas: só aceita se estiverem exatamente como neste arquivo.
    SELECT string_agg(c.nome, ', ' ORDER BY c.nome) INTO lista
      FROM carga_rotas c
      JOIN rotas r ON r.nome = c.nome
      LEFT JOIN veiculos v ON v.id = r.veiculo_id
     WHERE v.codigo IS DISTINCT FROM c.codigo
        OR NOT r.demonstrativo
        OR EXISTS (SELECT p.ordem, p.latitude, p.longitude FROM carga_rota_pontos p WHERE p.codigo = c.codigo
                   EXCEPT SELECT rp.ordem, rp.latitude, rp.longitude FROM rota_pontos rp WHERE rp.rota_id = r.id)
        OR EXISTS (SELECT rp.ordem, rp.latitude, rp.longitude FROM rota_pontos rp WHERE rp.rota_id = r.id
                   EXCEPT SELECT p.ordem, p.latitude, p.longitude FROM carga_rota_pontos p WHERE p.codigo = c.codigo);
    IF lista IS NOT NULL THEN
      RAISE EXCEPTION 'Rotas demonstrativas alteradas desde a carga: %. Nada foi alterado', lista;
    END IF;
    RAISE NOTICE 'As % rotas demonstrativas já estavam carregadas; nada foi alterado', total;

  ELSE
    RAISE EXCEPTION 'Carga parcial: % de % rotas demonstrativas já existem. Nada foi alterado; revise a tabela rotas', existentes, total;
  END IF;
END $$;

SELECT c.nome, v.id, true, true
  FROM carga_rotas c
  JOIN veiculos v ON v.codigo = c.codigo
 WHERE (SELECT carregar FROM carga_decisao)
 ORDER BY c.codigo;

SELECT r.id, p.ordem, p.latitude, p.longitude
  FROM carga_rota_pontos p
  JOIN carga_rotas c ON c.codigo = p.codigo
  JOIN rotas r ON r.nome = c.nome
 WHERE (SELECT carregar FROM carga_decisao);

COMMIT;
